urlset:
{# Sitemap entries lack source paths. Index parent covers from the canonical
   news inventory once, including each post's translated permalinks. #}
{%- set_global parent_previews = [] -%}
{%- set news = get_section(path="news/_index.md", lang=config.default_language, allow_missing=true) -%}
{%- if news -%}
  {%- for section_path in news.subsections -%}
    {%- set dated = get_section(path=section_path, lang=config.default_language) -%}
    {%- for post in dated.pages -%}
      {%- set image =  -%}
      {%- if image -%}
        {%- set_global parent_previews = [...parent_previews, {"permalink": post.permalink, "image": image}] -%}
        {%- for translation in post.translations -%}
          {%- if translation.permalink != post.permalink -%}
            {%- set_global parent_previews = [...parent_previews, {"permalink": translation.permalink, "image": image}] -%}
          {%- endif -%}
        {%- endfor -%}
      {%- endif -%}
    {%- endfor -%}
  {%- endfor -%}
{%- endif -%}
{%- set parent_previews = parent_previews | group_by(attribute="permalink") -%}
{%- for entry in entries %}

        {{ entry.permalink | escape_xml | safe }}
        {%- if entry.updated %}
        {{ entry.updated }}
        {%- endif %}
        {%- if entry.extra is defined and entry.extra.preview_image %}
        {%- set img = entry.extra.preview_image %}
        {#- Same resolution as base.html: a bare filename is one of the page's
            own colocated assets, which Zola copies into the page's own output
            directory, so it hangs off the permalink rather than the site root. -#}
        {%- if img is containing(pat='/') %}
        {%- set img_loc = config.base_url ~ '/' ~ (img | trim_start(pat='/')) -%}
        {%- else %}
        {%- set img_loc = entry.permalink ~ (img | urlencode) -%}
        {%- endif %}

            {{ img_loc | escape_xml | safe }}

        {%- else %}
        {%- set parent_preview = parent_previews | get(key=entry.permalink, default=[]) | first %}
        {%- if parent_preview %}

            {{ get_url(path=parent_preview.image) | escape_xml | safe }}

        {%- endif %}
        {%- endif %}

{%- endfor %}
